import React, { useEffect, useState } from 'react';
import { LineChart, Line, XAxis, YAxis, Tooltip, Legend } from 'recharts';
import axios from 'axios';

function App() {
  const [data, setData] = useState([]);

  useEffect(() => {
    const interval = setInterval(async () => {
      try {
        const res = await axios.get('http://localhost:5000/stats');
        const { downloadSpeed, uploadSpeed, cpuLoad, memoryUsed, memoryTotal } = res.data;

        setData(prev => [
          ...prev.slice(-20), // keep last 20 points
          {
            time: new Date().toLocaleTimeString(),
            downloadSpeed,
            uploadSpeed,
            cpuLoad,
            memoryUsed,
            memoryTotal,
          },
        ]);
      } catch (err) {
        console.error(err);
      }
    }, 1000); // fetch every 1 second

    return () => clearInterval(interval);
  }, []);

  return (
    <div style={{ padding: 20 }}>
      <h1>System & Download Monitor</h1>

      <h2>Network Speed (MB/s)</h2>
      <LineChart width={800} height={200} data={data}>
        <XAxis dataKey="time" />
        <YAxis />
        <Tooltip />
        <Legend />
        <Line type="monotone" dataKey="downloadSpeed" stroke="#8884d8" name="Download" />
        <Line type="monotone" dataKey="uploadSpeed" stroke="#82ca9d" name="Upload" />
      </LineChart>

      <h2>CPU Usage (%)</h2>
      <LineChart width={800} height={200} data={data}>
        <XAxis dataKey="time" />
        <YAxis />
        <Tooltip />
        <Line type="monotone" dataKey="cpuLoad" stroke="#ff7300" />
      </LineChart>

      <h2>Memory Usage (GB)</h2>
      <LineChart width={800} height={200} data={data}>
        <XAxis dataKey="time" />
        <YAxis />
        <Tooltip />
        <Legend />
        <Line type="monotone" dataKey="memoryUsed" stroke="#82aaff" name="Used" />
        <Line type="monotone" dataKey="memoryTotal" stroke="#ffaa82" name="Total" />
      </LineChart>
    </div>
  );
}

export default App;
